window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae6e986a81c167c3"]={"versions": [{"id": "FIG-ae6e986a81c167c3", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur formalen Metamodell-Definition der ECU-Konfigurationsparameter (ECUC Param Conf Container / Choice Container) des AUTOSAR Diagnostic Event Managers (Dem). Es spezifiziert die strukturellen Konfigurationscontainer, Auswahlmechanismen (Choice Containers) und Referenzen zur Festlegung der Entprellalgorithmen für Diagnose-Events.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li>DemEventParameter (EcucParamConfContainerDef, Multiplizität 1..65535): Repräsentiert das Diagnoseereignis; aggregiert über +subContainer exakt einen DemDebounceAlgorithmClass.\n</li><li>DemDebounceAlgorithmClass (EcucChoiceContainerDef, Multiplizität 1..1): Auswahlcontainer für die Entprellstrategie; enthält über +choice alternativ konfigurierbare Container (jeweils Multiplizität 0..1):\n<ul class=\"fig-list\"><li>DemDebounceTimeBase (EcucParamConfContainerDef): Aggregiert über +reference die Referenz DemDebounceTimeBaseRef (EcucReferenceDef, Multiplizität 1..1).\n</li><li>DemDebounceCounterBased (EcucParamConfContainerDef): Aggregiert über +reference die Referenz DemDebounceCounterBasedClassRef (EcucReferenceDef, Multiplizität 1..1).\n</li><li>DemDebounceMonitorInternal (EcucParamConfContainerDef): Aggregiert über +subContainer optional DemCallbackGetFDC (EcucParamConfContainerDef, Multiplizität 0..1), welches wiederum über +parameter den Funktionsnamen DemCallbackGetFDCFnc (EcucFunctionNameDef, Multiplizität 0..1) enthält.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Parametrierung legt statisch fest, ob die Entprellung für ein DemEventParameter zeitbasiert (über DemDebounceTimeBaseRef), zählerbasiert (über DemDebounceCounterBasedClassRef) oder monitorintern erfolgt. Bei monitorinterner Entprellung kann optional ein Callback zur Abfrage des Fault Detection Counters (FDC) über DemCallbackGetFDCFnc konfiguriert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfiguratoren und Codegeneratoren des Dem:</p>\n<ul class=\"fig-list\"><li>Pro DemEventParameter muss genau ein DemDebounceAlgorithmClass konfiguriert sein (Multiplizität 1..1).\n</li><li>Aus dem Choice-Container DemDebounceAlgorithmClass darf für ein Event genau eine der drei Entprellvarianten ausgewählt werden (DemDebounceTimeBase, DemDebounceCounterBased oder DemDebounceMonitorInternal).\n</li><li>Bei Wahl von DemDebounceTimeBase bzw. DemDebounceCounterBased ist die zugehörige Referenz (DemDebounceTimeBaseRef bzw. DemDebounceCounterBasedClassRef) mandatorisch (1..1).\n</li><li>DemCallbackGetFDC und der dazugehörige Callback-Name DemCallbackGetFDCFnc sind bei DemDebounceMonitorInternal optional (0..1).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-78b5b3b877b7b7c3", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm inklusive vorangestellter tabellarischer Übersicht („Configuration Parameters / Container Choices“) zur formalen Metamodell-Definition der ECU-Konfigurationsparameter des AUTOSAR Diagnostic Event Managers (Dem). Es spezifiziert die Konfigurationscontainer, Auswahlmechanismen (Choice Containers) und Referenzen zur Festlegung der Entprellalgorithmen für Diagnose-Events.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li>DemEventParameter (EcucParamConfContainerDef, Multiplizität 1..65535): Repräsentiert das Diagnoseereignis; aggregiert über +subContainer exakt einen DemDebounceAlgorithmClass.\n</li><li>DemDebounceAlgorithmClass (EcucChoiceContainerDef, Multiplizität 1..1): Auswahlcontainer für die Entprellstrategie; enthält über +choice alternativ konfigurierbare Container (jeweils Multiplizität 0..1):\n<ul class=\"fig-list\"><li>DemDebounceTimeBase (EcucParamConfContainerDef): Aggregiert über +reference die Referenz DemDebounceTimeBaseRef (EcucReferenceDef, Multiplizität 1..1).\n</li><li>DemDebounceCounterBased (EcucParamConfContainerDef): Aggregiert über +reference die Referenz DemDebounceCounterBasedClassRef (EcucReferenceDef, Multiplizität 1..1).\n</li><li>DemDebounceMonitorInternal (EcucParamConfContainerDef): Aggregiert über +subContainer optional DemCallbackGetFDC (EcucParamConfContainerDef, Multiplizität 0..1), welches wiederum über +parameter den Funktionsnamen DemCallbackGetFDCFnc (EcucFunctionNameDef, Multiplizität 0..1) enthält.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Parametrierung legt statisch fest, ob die Entprellung für ein DemEventParameter zeitbasiert (über DemDebounceTimeBaseRef), zählerbasiert (über DemDebounceCounterBasedClassRef) oder monitorintern erfolgt. Bei monitorinterner Entprellung kann optional ein Callback zur Abfrage des Fault Detection Counters (FDC) über DemCallbackGetFDCFnc konfiguriert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfiguratoren und Codegeneratoren des Dem:</p>\n<ul class=\"fig-list\"><li>Pro DemEventParameter muss genau ein DemDebounceAlgorithmClass konfiguriert sein (Multiplizität 1..1).\n</li><li>Aus dem Choice-Container DemDebounceAlgorithmClass darf für ein Event genau eine der drei Entprellvarianten ausgewählt werden (DemDebounceTimeBase, DemDebounceCounterBased oder DemDebounceMonitorInternal).\n</li><li>Bei Wahl von DemDebounceTimeBase bzw. DemDebounceCounterBased ist die zugehörige Referenz (DemDebounceTimeBaseRef bzw. DemDebounceCounterBasedClassRef) mandatorisch (1..1).\n</li><li>DemCallbackGetFDC und der dazugehörige Callback-Name DemCallbackGetFDCFnc sind bei DemDebounceMonitorInternal optional (0..1).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5ab7146cefd39496", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm mit einem oberen tabellarischen Teilausschnitt („DemDebounceMonitorInternal“, „DemDebounceTimeBase“) zur formalen Metamodell-Definition der ECU-Konfigurationsparameter des AUTOSAR Diagnostic Event Managers (Dem). Es spezifiziert Konfigurationscontainer, Auswahlmechanismen und Referenzen zur Konfiguration der Entprellalgorithmen für Diagnose-Events.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li>DemEventParameter (EcucParamConfContainerDef, Multiplizität 1..65535): Repräsentiert das Diagnoseereignis; aggregiert über +subContainer exakt einen DemDebounceAlgorithmClass.\n</li><li>DemDebounceAlgorithmClass (EcucChoiceContainerDef, Multiplizität 1..1): Auswahlcontainer für die Entprellstrategie; enthält über +choice alternativ konfigurierbare Container (jeweils Multiplizität 0..1):\n<ul class=\"fig-list\"><li>DemDebounceTimeBase (EcucParamConfContainerDef): Aggregiert über +reference die Referenz DemDebounceTimeBaseRef (EcucReferenceDef, Multiplizität 1..1).\n</li><li>DemDebounceCounterBased (EcucParamConfContainerDef): Aggregiert über +reference die Referenz DemDebounceCounterBasedClassRef (EcucReferenceDef, Multiplizität 1..1).\n</li><li>DemDebounceMonitorInternal (EcucParamConfContainerDef): Aggregiert über +subContainer optional DemCallbackGetFDC (EcucParamConfContainerDef, Multiplizität 0..1), welches wiederum über +parameter den Funktionsnamen DemCallbackGetFDCFnc (EcucFunctionNameDef, Multiplizität 0..1) enthält.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Parametrierung legt statisch fest, ob die Entprellung für ein DemEventParameter zeitbasiert (über DemDebounceTimeBaseRef), zählerbasiert (über DemDebounceCounterBasedClassRef) oder monitorintern erfolgt. Bei monitorinterner Entprellung kann optional ein Callback zur Abfrage des Fault Detection Counters (FDC) über DemCallbackGetFDCFnc konfiguriert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfiguratoren und Codegeneratoren des Dem:</p>\n<ul class=\"fig-list\"><li>Pro DemEventParameter muss genau ein DemDebounceAlgorithmClass konfiguriert sein (Multiplizität 1..1).\n</li><li>Aus dem Choice-Container DemDebounceAlgorithmClass darf für ein Event genau eine der drei Entprellvarianten ausgewählt werden (DemDebounceTimeBase, DemDebounceCounterBased oder DemDebounceMonitorInternal).\n</li><li>Bei Wahl von DemDebounceTimeBase bzw. DemDebounceCounterBased ist die zugehörige Referenz (DemDebounceTimeBaseRef bzw. DemDebounceCounterBasedClassRef) mandatorisch (1..1).\n</li><li>DemCallbackGetFDC und der dazugehörige Callback-Name DemCallbackGetFDCFnc sind bei DemDebounceMonitorInternal optional (0..1).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ae6e986a81c167c3", "to": "FIG-78b5b3b877b7b7c3", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberhalb des Klassendiagramms wurde eine tabellarische Übersicht („Configuration Parameters / Container Choices“) für die Auswahl-Container DemDebounceCounterBased, DemDebounceMonitorInternal und DemDebounceTimeBase mit Spalten für Multiplicity und Scope / Dependency eingefügt.\n</li><li>Im Klassendiagramm wurden Bezeichnerformatierungen und Doppelpunkte nach Containernamen typografisch vereinheitlicht.\n</li></ul>"}, {"from": "FIG-78b5b3b877b7b7c3", "to": "FIG-5ab7146cefd39496", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In der vorangestellten Tabelle wurde die Kopfzeile („Configuration Parameters“ / „Container Choices / Container Name / Multiplicity / Scope / Dependency“) sowie die erste Datenzeile für DemDebounceCounterBased abgeschnitten/entfernt, sodass die Tabelle fragmentarisch erst bei DemDebounceMonitorInternal beginnt.\n</li></ul>"}]};
